/** A built-in title: an original summary of a popular nonfiction book, ready to read and hear. */
data class Book(
    val id: String,
    val title: String,
    val author: String,
    val year: Int,
    val blurb: String,
    val color: Long,
    val visual: VisualStyle,
    val summary: String,
)

const val CUSTOM_BOOK_ID = "custom"

private val DOCUMENTS = HashMap<String, Document>()

/** The parsed summary, built once per title. */
val Book.document: Document get() = synchronized(DOCUMENTS) { DOCUMENTS.getOrPut(id) { Document(summary) } }

